<?php require __DIR__.'/../header.php';require __DIR__.'/../navbar.php';?><main class="container-fluid py-4 px-lg-4"><div class="col-lg-8"><h1 class="h3">Nueva rendición</h1><p class="text-secondary">Seleccioná pagos del mismo vendedor y campaña. El monto se calcula automáticamente como la suma de los pagos.</p><?php if(isset($error)):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><?php if(!$pagosDisponibles):?><div class="alert alert-info">No hay pagos disponibles para rendir.</div><?php else:?><form method="post" class="card p-4"><div class="mb-3"><label class="form-label">Pagos incluidos</label><?php foreach($pagosDisponibles as $p):?><label class="d-flex align-items-start gap-2 border rounded p-2 mb-2"><input class="form-check-input" type="checkbox" name="pagos[]" value="<?=e($p['id'])?>"><span>Pago #<?=e($p['id'])?> · <?=e($p['campania'])?> · <?=e($p['vendedor'])?> · <?=e($p['cliente'])?> · <strong>$<?=number_format($p['monto'],2,',','.')?></strong></span></label><?php endforeach;?></div><label class="form-label">Fecha</label><input class="form-control mb-3" type="date" name="fecha_rendicion" value="<?=date('Y-m-d')?>" required><label class="form-label">Observación</label><textarea class="form-control mb-3" name="observacion"></textarea><div class="d-flex gap-2"><button class="btn btn-primary">Enviar rendición</button><a class="btn btn-light" href="index.php?c=rendicion&a=inicio">Cancelar</a></div></form><?php endif;?></div></main><?php require __DIR__.'/../footer.php';?>